#!/bin/sh
# install.sh — install the Harbor CLI from GitHub release archives.
#
# One-liner (curl | sh):
#   curl -fsSL https://raw.githubusercontent.com/harbor-sh/harbor/dev/dist/install.sh | sh
#   curl -fsSL https://raw.githubusercontent.com/harbor-sh/harbor/dev/dist/install.sh | sh -s -- --tag v0.7.0
#
# What it does: downloads the .tar.gz published by the NUKE Release target
# (see build/_build/Targets/ReleaseTarget.cs — 3 variants x TarGz) and
# installs it into $PREFIX/lib/harbor plus a $PREFIX/bin/harbor shim
# (default PREFIX=/usr/local). No native package manager required.
#
# For a managed install, build a .deb instead:
#   packaging/deb/build-deb.sh --archive <release-tar.gz> --version <x.y.z>
#
# Options:
#   --tag TAG       release tag, e.g. v0.7.0 (default: latest release)
#   --repo OWNER/NAME
#                   GitHub repo (default: harbor-sh/harbor — same default as
#                   the NUKE Release target's --release-repo)
#   --variant V     FrameworkDependent | SelfContained | SingleFileSelfContained
#                   (default: SelfContained — runs without a dotnet runtime)
#   --rid RID       runtime id, e.g. linux-x64 (default: auto-detected)
#   --prefix DIR    install prefix (default: $PREFIX or /usr/local;
#                   use --prefix ~/.local for a rootless install)
#   -h, --help      print this help and exit
#
# Requirements: curl or wget, tar, sh. FrameworkDependent additionally needs
# a .NET 10 runtime on PATH (the shim execs `dotnet ...` in that case).
set -eu

REPO="${HARBOR_REPO:-harbor-sh/harbor}"
TAG="${HARBOR_TAG:-}"
VARIANT="${HARBOR_VARIANT:-SelfContained}"
RID=""
PREFIX="${PREFIX:-/usr/local}"

usage() {
    sed -n '2,/^set -eu$/p' "$0" | sed 's/^# \{0,1\}//'
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --tag) TAG="$2"; shift 2 ;;
        --tag=*) TAG="${1#--tag=}"; shift ;;
        --repo) REPO="$2"; shift 2 ;;
        --repo=*) REPO="${1#--repo=}"; shift ;;
        --variant) VARIANT="$2"; shift 2 ;;
        --variant=*) VARIANT="${1#--variant=}"; shift ;;
        --rid) RID="$2"; shift 2 ;;
        --rid=*) RID="${1#--rid=}"; shift ;;
        --prefix) PREFIX="$2"; shift 2 ;;
        --prefix=*) PREFIX="${1#--prefix=}"; shift ;;
        -h|--help) usage; exit 0 ;;
        *) echo "install.sh: unknown argument '$1' (try --help)" >&2; exit 2 ;;
    esac
done

# Variant slug must stay in sync with
# build/_build/Components/ArtifactPathResolver.cs (GetVariantDirName).
case "$VARIANT" in
    FrameworkDependent) SLUG="framework-dependent" ;;
    SelfContained) SLUG="self-contained" ;;
    SingleFileSelfContained) SLUG="single-file-self-contained" ;;
    *) echo "install.sh: unknown --variant '$VARIANT' (want FrameworkDependent|SelfContained|SingleFileSelfContained)" >&2; exit 2 ;;
esac

# RID slug: NUKE replaces '-' with '_' in the archive name
# (GetArchiveBaseName), e.g. linux-x64 -> linux_x64.
if [ -z "$RID" ]; then
    OS="$(uname -s)"; ARCH="$(uname -m)"
    case "$OS" in
        Linux) RID="linux" ;;
        Darwin) RID="osx" ;;
        *) echo "install.sh: unsupported OS '$OS' (override with --rid)" >&2; exit 2 ;;
    esac
    case "$ARCH" in
        x86_64|amd64) RID="$RID-x64" ;;
        arm64|aarch64) RID="$RID-arm64" ;;
        *) echo "install.sh: unsupported arch '$ARCH' (override with --rid)" >&2; exit 2 ;;
    esac
fi
RID_SLUG="$(printf '%s' "$RID" | tr '-' '_')"

ASSET="harbor-cli-${SLUG}-${RID_SLUG}.tar.gz"
if [ -n "$TAG" ]; then
    URL="https://github.com/${REPO}/releases/download/${TAG}/${ASSET}"
else
    URL="https://github.com/${REPO}/releases/latest/download/${ASSET}"
fi

echo "harbor install: ${REPO} ${TAG:-latest} ${ASSET}"
echo "harbor install: ${URL}"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT INT TERM
if command -v curl >/dev/null 2>&1; then
    curl -fsSL -o "$TMP/harbor.tar.gz" "$URL"
elif command -v wget >/dev/null 2>&1; then
    wget -qO "$TMP/harbor.tar.gz" "$URL"
else
    echo "install.sh: need curl or wget on PATH" >&2; exit 1
fi
command -v tar >/dev/null 2>&1 || { echo "install.sh: need tar on PATH" >&2; exit 1; }

mkdir -p "$TMP/pkg" "$PREFIX/lib/harbor" "$PREFIX/bin"
tar -xzf "$TMP/harbor.tar.gz" -C "$TMP/pkg"
cp -r "$TMP/pkg/." "$PREFIX/lib/harbor/"

# Shim: self-contained publishes a native Harbor.App.Cli next to the
# framework-dependent Harbor.App.Cli.dll — prefer the native binary.
cat > "$PREFIX/bin/harbor" <<EOF
#!/bin/sh
# Generated by Harbor dist/install.sh — do not edit.
HARBOR_LIB="$PREFIX/lib/harbor"
if [ -x "\$HARBOR_LIB/Harbor.App.Cli" ]; then
    exec "\$HARBOR_LIB/Harbor.App.Cli" "\$@"
else
    exec dotnet "\$HARBOR_LIB/Harbor.App.Cli.dll" "\$@"
fi
EOF
chmod +x "$PREFIX/bin/harbor"

if [ -x "$PREFIX/lib/harbor/Harbor.App.Cli" ]; then
    :
elif ! command -v dotnet >/dev/null 2>&1; then
    echo "install.sh: warning: framework-dependent install but no dotnet runtime on PATH" >&2
fi

echo "harbor install: done — $PREFIX/bin/harbor"
"$PREFIX/bin/harbor" --version || echo "harbor install: warning: smoke run failed" >&2
